scripts.script:
if (args.isHit) {
    const prone = CONFIG.statusEffects.find(e => e.id === 'prone');
    await game.xjzl.api.effects.addEffect(args.target, prone);

    const rootData = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === 'root'));
    rootData.duration = { rounds: 1 };
    await game.xjzl.api.effects.addEffect(args.target, rootData);
}

if (!actor.system.martial.stanceActive) {
    args.flags.abort = true;
    args.flags.abortReason = '王车易位：只能在自身开启架招的情况下使用！';
}

await actor.stopStance();
await game.xjzl.api.effects.removeEffect(args.target, 'pofang', 1);
ChatMessage.create({
    content: `<div class="xjzl-chat-card"><div style="padding:5px; border-left:4px solid #2980b9; background:rgba(41, 128, 185, 0.1);"><p><i class="fas fa-chess-king"></i> <b>王车易位</b></p><p>${actor.name} 撤去了防御姿态，为 ${args.target.name} 挡下了破绽！</p><p style="color:#2980b9; margin-top:5px;">请 <b>${args.target.name}</b> 尽快手动点击面板开启架招。</p></div></div>`,
    speaker: ChatMessage.getSpeaker({actor: actor})
});

const eff = thisItem.effects.getName('入木三分').toObject();
delete eff._id;
eff.origin = thisItem.uuid;
eff.duration = { rounds: 1 };
await game.xjzl.api.effects.addEffect(actor, eff);
ChatMessage.create({
    content: `<div class="xjzl-chat-card"><div style="padding:5px; border-left:4px solid #16a085;"><p><i class="fas fa-pen-nib"></i> 力透纸背，获得了 <b>[入木三分]</b> 状态！</p><p style="font-size:0.85em; color:#555;">请在后续主动动作中：<br>1. 弹窗时手动将实招类型修改为“虚招”。<br>2. 若成功击破架招，请根据招式距离手动增加额外伤害。</p></div></div>`,
    speaker: ChatMessage.getSpeaker({actor: actor})
});

const options = `<option value="unarmed">徒手 (外/内防+5)</option><option value="sword">剑 (距离+2)</option><option value="hidden">暗器 (虚招+1)</option><option value="staff">长棍 (太极招式伤害+10)</option>`;
const content = `<form><div class="form-group"><label>选择化气为兵类型：</label><select name="wType">${options}</select></div></form>`;
const wType = await foundry.applications.api.DialogV2.prompt({
    window: { title: '化气为兵' },
    content: content,
    ok: { callback: (ev, btn) => btn.form.elements.wType.value }
});
if (!wType) {
    args.flags.abort = true;
    return;
}

// 将选择的值存入 flags，供 hit 脚本提取
args.flags.selectedWType = wType;

const wType = args.flags.selectedWType;
if (wType) {
    const eff = thisItem.effects.getName(`枫桦气兵-${wType}`);
    if (eff) {
        const eData = eff.toObject();
        delete eData._id;
        eData.origin = thisItem.uuid;
        await game.xjzl.api.effects.addEffect(actor, eData);
        ui.notifications.info(`已化气为兵: ${wType}`);
    }
}

ChatMessage.create({
    content: `<div class="xjzl-chat-card"><div style="padding:5px; border-left:4px solid #f1c40f; background:rgba(241, 196, 15, 0.1);"><p><i class="fas fa-om"></i> <b>嗡</b></p><p>断除堕落。请 <b>${args.target.name}</b> 停止一项地级及以下状态的生效（可在状态栏中将其暂时禁用）。</p></div></div>`,
    speaker: ChatMessage.getSpeaker({actor: actor})
});

const lvl = Math.max(1, move.computedLevel || 1);
const rounds = Math.max(1, 3 - (lvl - 1));
ChatMessage.create({
    content: `<div class="xjzl-chat-card"><div style="padding:5px; border-left:4px solid #f1c40f; background:rgba(241, 196, 15, 0.1);"><p><i class="fas fa-om"></i> <b>嘛</b></p><p>${actor.name} 开始念诵【嘛】字诀，心无旁骛。</p><p style="color:#d35400; margin-top:5px;">如果在接下来的 <b>${rounds}</b> 个回合内没有遭受攻击，即可强制脱离战斗！</p></div></div>`,
    speaker: ChatMessage.getSpeaker({actor: actor})
});

const lvl = Math.max(1, move.computedLevel || 1);
const shield = 10 + (lvl - 1) * 5;
await actor.applyHealing({ healer: actor,  amount: shield, type: 'huti', showScrolling: true });

const lvl = Math.max(1, move.computedLevel || 1);
const healMp = 5 + (lvl - 1) * 5;
await args.target.applyHealing({ healer: actor,  amount: healMp, type: 'mp', showScrolling: true });
ChatMessage.create({
    content: `<div class="xjzl-chat-card"><div style="padding:5px; border-left:4px solid #e74c3c; background:rgba(231, 76, 60, 0.1);"><p><i class="fas fa-om"></i> <b>咩</b></p><p>佛音清心，请手动检查 <b>${args.target.name}</b> 身上是否有 烈女吟、情花毒 等情蛊相关状态并将其移除。</p></div></div>`,
    speaker: ChatMessage.getSpeaker({actor: actor})
});

ChatMessage.create({
    content: `<div class="xjzl-chat-card"><div style="padding:5px; border-left:4px solid #3498db; background:rgba(52, 152, 219, 0.1);"><p><i class="fas fa-om"></i> <b>吽</b></p><p>寒热不侵。请手动去除 <b>${args.target.name}</b> 身上的[冻伤]或[引燃]状态。</p></div></div>`,
    speaker: ChatMessage.getSpeaker({actor: actor})
});

if (!args.isHit) return;

// ==========================================
// 1. 受击质变判定 (气促满3层触发转化)
// ==========================================
const qicu = args.target.effects.find(e => e.getFlag('xjzl-system', 'slug') === 'wuxue_qicu');
const qcStacks = qicu ? (qicu.getFlag('xjzl-system', 'stacks') || 1) : 0;

if (qcStacks >= 3) {
    // 清空全部气促
    await game.xjzl.api.effects.removeEffect(args.target, 'wuxue_qicu', qcStacks);
    actor.showFloatyText('经脉受堵！', { fill: '#8e44ad' });

    const jm = args.target.effects.find(e => e.getFlag('xjzl-system', 'slug') === 'wuxue_jingmaiduse');
    const jmStacks = jm ? (jm.getFlag('xjzl-system', 'stacks') || 1) : 0;

    // 检查：如果现存经脉堵塞 >= 2层，加上本次的1层即满3层，直接爆破
    if (jmStacks >= 2) {
        if (jm) await game.xjzl.api.effects.removeEffect(args.target, 'wuxue_jingmaiduse', jmStacks);
        ChatMessage.create({
            content: `<div class="xjzl-chat-card"><div style="padding:5px; border-left:4px solid red; background:rgba(255,0,0,0.1);"><p><i class="fas fa-skull"></i> <b style="color:red; font-size:1.2em;">丹田破碎！</b></p><p>${args.target.name} 的丹田被彻底摧毁！</p></div></div>`,
            speaker: ChatMessage.getSpeaker({actor: args.target})
        });
    } else {
        // 否则正常叠一层经脉堵塞
        const jmData = thisItem.effects.getName('经脉堵塞').toObject();
        delete jmData._id;
        jmData.origin = thisItem.uuid;
        await game.xjzl.api.effects.addEffect(args.target, jmData);
    }
}

// ==========================================
// 2. 照常发起角力对抗
// ==========================================
const qcData = thisItem.effects.getName('气促').toObject();
delete qcData._id;
qcData.origin = thisItem.uuid;

await Macros.requestContest({
    attacker: actor,
    defender: args.target,
    type: 'liliang',
    label: '狮子印 - 角力压制',
    outcome: {
        win: {
            text: '角力压制成功！目标流失内力并附加气促。',
            targetDamage: { value: 5, type: 'mp' },
            targetEffect: qcData
        },
        lose: { text: '角力失败，目标未受影响。' }
    }
});

if (!Macros.checkStance(actor, args)) return;
if (!args.attacker) return;

await args.attacker.applyHealing({ healer: actor,  amount: -5, type: 'mp', showScrolling: true });

const qcData = thisItem.effects.getName('气促').toObject();
delete qcData._id;
qcData.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(args.attacker, qcData);

const used = actor.getFlag('xjzl-system', 'wuxue_ranzhi_used') || 0;
const lvl = Math.max(1, move.computedLevel || 1);
const limit = 1 + (lvl - 1);
if (used >= limit) {
    args.flags.abort = true;
    args.flags.abortReason = `燃指供佛：本场战斗使用次数已达上限（${limit}次）！`;
}

const u = actor.getFlag('xjzl-system', 'wuxue_ranzhi_used') || 0;
await actor.setFlag('xjzl-system', 'wuxue_ranzhi_used', u + 1);

const lvl = Math.max(1, move.computedLevel || 1);
const pct = 0.2 + (lvl - 1) * 0.1;
const hpHeal = Math.floor(S.resources.hp.max * pct);
const mpHeal = Math.floor(S.resources.mp.max * pct);

await actor.applyHealing({ healer: actor, amount: hpHeal, type: 'hp', showScrolling: true});
await actor.applyHealing({ healer: actor, amount: mpHeal, type: 'mp', showScrolling: true});

const eff = thisItem.effects.getName('燃指之力').toObject();
delete eff._id;
eff.origin = thisItem.uuid;
const bonusVal = 20 + (lvl - 1) * 10;
eff.changes[0].value = String(bonusVal);
eff.changes[1].value = String(bonusVal);
await game.xjzl.api.effects.addEffect(actor, eff);

ChatMessage.create({
    content: `<div class="xjzl-chat-card" style="border-left: 4px solid red; padding: 5px; background:rgba(255,0,0,0.05);">
        <p><b style="color:#c0392b; font-size:1.1em;"><i class="fas fa-fire"></i> 燃指供佛</b></p>
        <p>失去了一根手指！(请玩家手动记录残疾)</p>
        <p>向佛陀献祭，恢复了 ${Math.floor(pct * 100)}% 的气血与内力，并获得招式伤害与格挡 +${bonusVal}！</p>
        <p style="font-size:0.8em; color:#888; margin-top:5px;">注意：燃烧的躯体不可用常规手段恢复。</p>
    </div>`,
    speaker: ChatMessage.getSpeaker({actor: actor})
});

const lvl = Math.max(1, move.computedLevel || 1);
const rounds = 1 + (lvl - 1);
const eff = thisItem.effects.getName("轮墓").toObject();
delete eff._id;
eff.origin = thisItem.uuid;
eff.duration = { rounds: rounds };
await game.xjzl.api.effects.addEffect(actor, eff);

const parentMove = thisItem.system.moves.find(m => m.name === "五轮飞转");
const lvl = Math.max(1, parentMove?.computedLevel || 1);
if (lvl > 1) {
    const bonus = (lvl - 1) * 10;
    args.output.damage += bonus;
    args.output.bonusDesc.push(`五轮飞转等级加成: +${bonus}`);
}

if(args.isHit) {
    const yishang = CONFIG.statusEffects.find(e => e.id === "yishang");
    await game.xjzl.api.effects.addEffect(args.target, yishang);
    ui.notifications.info(`${args.target.name} 受到轮墓割裂，获得易伤！`);
}

if(args.isHit) {
    const yishang = CONFIG.statusEffects.find(e => e.id === "yishang");
    await game.xjzl.api.effects.addEffect(args.target, yishang);

    if(args.finalDamage > 0) {
        const content = `
        <div class="xjzl-chat-card">
            <div style="padding: 5px; padding-left: 8px; border-left: 4px solid #d35400; background: rgba(211, 84, 0, 0.1); margin-left: 2px;">
                <div style="font-weight: bold; color: #d35400; font-size: 1.1em;"><i class="fas fa-wind"></i> 轮风激荡！</div>
                <div style="font-size: 0.9em; margin-top: 5px; color: #555;">
                    对 ${args.target.name} 造成了 <b>${args.finalDamage}</b> 点实际伤害。<br>
                    <span style="color: #c0392b; font-weight: bold;">请手动对目标一格范围内的所有敌方，造成 ${args.finalDamage} 点内功伤害！</span>
                </div>
            </div>
        </div>`;
        ChatMessage.create({ content: content, speaker: ChatMessage.getSpeaker({actor: actor}) });
    }
}

if(!Macros.checkStance(actor, args)) return;
if(args.attacker) {
    const yishang = CONFIG.statusEffects.find(e => e.id === "yishang");
    await game.xjzl.api.effects.addEffect(args.attacker, yishang);
}
const eff = thisItem.effects.getName("边狱").toObject();
delete eff._id;
eff.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(actor, eff);
actor.showFloatyText("边狱展开！", { fill: "#9b59b6" });
